/* Variáveis de tema */
:root{
  --bg: #f2f3f5;
  --card: #ffffff;
  --display-bg: #1f2937; /* dark display */
  --text-display: #ffffff;
  --btn-num: #f4f4f4;
  --btn-fn: #d3d6db;
  --btn-op: #ff9f0a;
  --btn-op-text: #ffffff;
  --shadow: 0 8px 24px rgba(16,24,40,0.08);
}

*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0; font-family: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; background:var(--bg); display:flex; align-items:center; justify-content:center; padding:24px;
}
.page{width:100%; max-width:460px}
.calculator{
  background:var(--card); border-radius:36px; padding:20px; box-shadow:var(--shadow);
}
.display{
  background:linear-gradient(180deg,#1f2937,#111827); color:var(--text-display); font-size:48px; text-align:right; padding:28px 18px; border-radius:18px; margin-bottom:16px; min-height:72px; display:flex; align-items:center; justify-content:flex-end; font-weight:600; overflow:hidden; white-space:nowrap;
}
.keys{display:grid; grid-template-columns:repeat(4,1fr); gap:12px}
.btn{background:var(--btn-num); border:0; padding:18px; font-size:20px; border-radius:14px; box-shadow:0 4px 10px rgba(16,24,40,0.06); cursor:pointer; transition:transform .06s ease, box-shadow .06s ease}
.btn:active{transform:translateY(2px)}
.btn:focus{outline:2px solid rgba(0,0,0,0.12); outline-offset:2px}
.btn-fn{background:var(--btn-fn)}
.btn-op{background:var(--btn-op); color:var(--btn-op-text)}
.btn-zero{grid-column:span 2; text-align:left; padding-left:28px}
.btn-equals{background:var(--btn-op); color:var(--btn-op-text); grid-column:span 1}

/* Responsividade */
@media (min-width:600px){
  .display{font-size:64px; min-height:96px}
  .btn{padding:22px; font-size:22px}
}

/* Pequeno ajuste para mobile estreito */
@media (max-width:360px){
  .calculator{padding:14px}
  .display{font-size:40px; padding:18px}
  .btn{padding:14px; font-size:18px}
}

